import type { WisdomArticle } from "./types";

/** Articles sourced verbatim from temp-content/p3.txt (link-scrubbed, headings normalized) */
export const p3Articles: WisdomArticle[] = [
  {
    id: "western-differences",
    section: "introduction",
    title: { en: `Vedic and Western Astrology: Key Differences`, ja: `Vedic and Western Astrology: Key Differences` },
    related: ["paradigm-shift","sidereal-zodiac-p3","key-differences-intro"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Vedic and Western Astrology: Key Differences`, ja: `Vedic and Western Astrology: Key Differences` } },
      { type: "paragraph", text: { en: `Summary: This article explores the major differences between Vedic Astrology and Western Astrology. The Vedic system differs significantly from the Western approach in its origins (through Vedic cognition), underlying paradigms (predictive, preventive, karmic, and based on coded information rather than planetary forces), and methodology (including the use of only nine planets, the sidereal zodiac, functional benefics, Mahadasha timing systems, and more).`, ja: `Summary: This article explores the major differences between Vedic Astrology and Western Astrology. The Vedic system differs significantly from the Western approach in its origins (through Vedic cognition), underlying paradigms (predictive, preventive, karmic, and based on coded information rather than planetary forces), and methodology (including the use of only nine planets, the sidereal zodiac, functional benefics, Mahadasha timing systems, and more).` } },
      { type: "heading", level: 3, text: { en: `Different Systems – Different Strengths`, ja: `Different Systems – Different Strengths` } },
      { type: "paragraph", text: { en: `When we examine both Vedic Astrology and Western Astrology, it becomes clear that each system possesses its own unique strengths.`, ja: `When we examine both Vedic Astrology and Western Astrology, it becomes clear that each system possesses its own unique strengths.` } },
      { type: "paragraph", text: { en: `Western Astrology generally places greater emphasis on psychology and the workings of the mind. As a result, a Western birth chart can provide an excellent foundation for counselling and self-reflection. For those seeking deeper understanding of their thoughts, emotions, and inner psychological nature, Western Astrology offers valuable insights.`, ja: `Western Astrology generally places greater emphasis on psychology and the workings of the mind. As a result, a Western birth chart can provide an excellent foundation for counselling and self-reflection. For those seeking deeper understanding of their thoughts, emotions, and inner psychological nature, Western Astrology offers valuable insights.` } },
      { type: "paragraph", text: { en: `Vedic Astrology, by contrast, focuses more strongly on karma and the prediction of how karmic influences will unfold throughout life, including the timing of those events. It is distinctive in offering remedial measures designed to reduce or soften the impact of returning negative karmas. In this way, Vedic Astrology is both predictive and preventive, while also providing practical solutions to many of life's challenges.`, ja: `Vedic Astrology, by contrast, focuses more strongly on karma and the prediction of how karmic influences will unfold throughout life, including the timing of those events. It is distinctive in offering remedial measures designed to reduce or soften the impact of returning negative karmas. In this way, Vedic Astrology is both predictive and preventive, while also providing practical solutions to many of life's challenges.` } },
      { type: "paragraph", text: { en: `While these observations are broad generalizations—and astrologers from both traditions would no doubt enjoy debating them—they help illustrate the different areas of emphasis within Western and Vedic Astrology.`, ja: `While these observations are broad generalizations—and astrologers from both traditions would no doubt enjoy debating them—they help illustrate the different areas of emphasis within Western and Vedic Astrology.` } },
      { type: "heading", level: 3, text: { en: `Vedic Astrology – Predictive and Preventive`, ja: `Vedic Astrology – Predictive and Preventive` } },
      { type: "paragraph", text: { en: `Jyotish is fundamentally predictive. It identifies potential opportunities and obstacles across all major areas of life, including health, home, wealth, income, children, career, relationships, and spiritual development.[1] It forecasts both favorable periods and more challenging phases that may arise in the future. In doing so, it seeks to identify returning karmas and determine when they are most likely to manifest.`, ja: `Jyotish is fundamentally predictive. It identifies potential opportunities and obstacles across all major areas of life, including health, home, wealth, income, children, career, relationships, and spiritual development.[1] It forecasts both favorable periods and more challenging phases that may arise in the future. In doing so, it seeks to identify returning karmas and determine when they are most likely to manifest.` } },
      { type: "paragraph", text: { en: `Jyotish is also preventive. It employs a wide range of remedial measures intended to influence an individual's returning karma. This ability to prescribe remedies that help rebalance planetary energies, as revealed in the birth chart, is one of the unique characteristics of Jyotish. At its core, Vedic Astrology can therefore be viewed as a form of karmic engineering.`, ja: `Jyotish is also preventive. It employs a wide range of remedial measures intended to influence an individual's returning karma. This ability to prescribe remedies that help rebalance planetary energies, as revealed in the birth chart, is one of the unique characteristics of Jyotish. At its core, Vedic Astrology can therefore be viewed as a form of karmic engineering.` } },
      { type: "paragraph", text: { en: `Jyotish additionally includes techniques for determining the most favorable timing for important activities such as starting a business, getting married, building a home, or undertaking other major ventures. This branch of astrology is known as Muhurta. As the saying goes, "Well begun is half done."`, ja: `Jyotish additionally includes techniques for determining the most favorable timing for important activities such as starting a business, getting married, building a home, or undertaking other major ventures. This branch of astrology is known as Muhurta. As the saying goes, "Well begun is half done."` } },
      { type: "heading", level: 3, text: { en: `Jyotish Astrology: Cognized – Not Developed`, ja: `Jyotish Astrology: Cognized – Not Developed` } },
      { type: "paragraph", text: { en: `Unlike Western Astrology, which evolved through centuries of human development and refinement, Jyotish was cognized. According to Vedic understanding, a great seer or Rishi—in this case Maharishi Parashara—connected individual consciousness with the universal field of intelligence and "downloaded" the complete knowledge and techniques of Vedic Astrology.`, ja: `Unlike Western Astrology, which evolved through centuries of human development and refinement, Jyotish was cognized. According to Vedic understanding, a great seer or Rishi—in this case Maharishi Parashara—connected individual consciousness with the universal field of intelligence and "downloaded" the complete knowledge and techniques of Vedic Astrology.` } },
      { type: "paragraph", text: { en: `For this reason, Jyotish Astrologers regard their discipline with deep respect, viewing it as a divine gift intended to help reduce human suffering.`, ja: `For this reason, Jyotish Astrologers regard their discipline with deep respect, viewing it as a divine gift intended to help reduce human suffering.` } },
      { type: "paragraph", text: { en: `Vedic Astrology originates from the same ancient tradition that gave rise to Yoga, Meditation, Pranayama, Ayurveda, and Vastu.`, ja: `Vedic Astrology originates from the same ancient tradition that gave rise to Yoga, Meditation, Pranayama, Ayurveda, and Vastu.` } },
      { type: "heading", level: 3, text: { en: `Vedic Astrology Only Needs to Use Nine ‘Planets’`, ja: `Vedic Astrology Only Needs to Use Nine ‘Planets’` } },
      { type: "paragraph", text: { en: `Traditional Jyotish uses only nine Grahas—commonly translated as the nine "planets." These consist of the seven visible planets up to Saturn, along with the two lunar nodes. Unlike Western Astrology, it does not incorporate the planets beyond Saturn because it simply has no need to do so.`, ja: `Traditional Jyotish uses only nine Grahas—commonly translated as the nine "planets." These consist of the seven visible planets up to Saturn, along with the two lunar nodes. Unlike Western Astrology, it does not incorporate the planets beyond Saturn because it simply has no need to do so.` } },
      { type: "paragraph", text: { en: `In Vedic Astrology, all the information required for prediction is encoded within the arrangement of these nine planets at the moment of birth. The later movement of planets through transit generally carries less predictive weight.`, ja: `In Vedic Astrology, all the information required for prediction is encoded within the arrangement of these nine planets at the moment of birth. The later movement of planets through transit generally carries less predictive weight.` } },
      { type: "paragraph", text: { en: `The positioning of the seven visible planets and the two lunar nodes among the twelve signs, twelve houses, and twenty-seven Nakshatras represents a highly sophisticated system of coded information. Likewise, planetary transits through signs and houses are interpreted as encoded information rather than as physical influences.`, ja: `The positioning of the seven visible planets and the two lunar nodes among the twelve signs, twelve houses, and twenty-seven Nakshatras represents a highly sophisticated system of coded information. Likewise, planetary transits through signs and houses are interpreted as encoded information rather than as physical influences.` } },
      { type: "paragraph", text: { en: `If you encounter a "Jyotish Astrologer" who incorporates Uranus, Neptune, or Pluto, they are not practicing Traditional Jyotish Astrology but have instead blended elements from the two systems. Such an approach overlooks the fundamental concept of coded information.`, ja: `If you encounter a "Jyotish Astrologer" who incorporates Uranus, Neptune, or Pluto, they are not practicing Traditional Jyotish Astrology but have instead blended elements from the two systems. Such an approach overlooks the fundamental concept of coded information.` } },
      { type: "paragraph", text: { en: `Because Vedic Astrology views the universe and all living beings as part of an interconnected field of energy, order, and intelligence, it works primarily with coded information.`, ja: `Because Vedic Astrology views the universe and all living beings as part of an interconnected field of energy, order, and intelligence, it works primarily with coded information.` } },
      { type: "paragraph", text: { en: `Western Astrology, on the other hand, is often more Newtonian and mechanistic in outlook. It tends to imply that planets emit some form of influence or force—yet to be identified by modern science—that affects human beings on Earth. Consequently, whenever astronomers discover a new celestial object within the solar system, Western Astrology must adapt and assign astrological meanings to that object.`, ja: `Western Astrology, on the other hand, is often more Newtonian and mechanistic in outlook. It tends to imply that planets emit some form of influence or force—yet to be identified by modern science—that affects human beings on Earth. Consequently, whenever astronomers discover a new celestial object within the solar system, Western Astrology must adapt and assign astrological meanings to that object.` } },
      { type: "paragraph", text: { en: `Jyotish considers this unnecessary. It does not require the concept of planetary forces acting upon people. Instead, it interprets the coded information contained within planetary positions and configurations.`, ja: `Jyotish considers this unnecessary. It does not require the concept of planetary forces acting upon people. Instead, it interprets the coded information contained within planetary positions and configurations.` } },
      { type: "heading", level: 3, text: { en: `A Unique System of Time-Based Predictions – The Mahadashas`, ja: `A Unique System of Time-Based Predictions – The Mahadashas` } },
      { type: "paragraph", text: { en: `One of the most distinctive features of Jyotish is its Mahadasha system, which identifies major periods of karmic influence throughout life.`, ja: `One of the most distinctive features of Jyotish is its Mahadasha system, which identifies major periods of karmic influence throughout life.` } },
      { type: "paragraph", text: { en: `Like Western Astrology, Jyotish also considers planetary transits. However, in most cases, transits are far less significant than the Mahadashas when making predictions.`, ja: `Like Western Astrology, Jyotish also considers planetary transits. However, in most cases, transits are far less significant than the Mahadashas when making predictions.` } },
      { type: "paragraph", text: { en: `Mahadasha periods are essential for accurate forecasting. They allow the static factors represented by planetary placements in houses and signs to interact with the dynamic flow of time. This combination enables astrologers to determine both what is likely to happen and when it is likely to happen.`, ja: `Mahadasha periods are essential for accurate forecasting. They allow the static factors represented by planetary placements in houses and signs to interact with the dynamic flow of time. This combination enables astrologers to determine both what is likely to happen and when it is likely to happen.` } },
      { type: "heading", level: 3, text: { en: `Ascendant of Key Importance in Jyotish`, ja: `Ascendant of Key Importance in Jyotish` } },
      { type: "paragraph", text: { en: `In Vedic Astrology, the Ascendant—the sign rising on the eastern horizon at the moment of birth—is of central importance. By comparison, the Sun sign emphasized in Western Astrology carries relatively little significance.`, ja: `In Vedic Astrology, the Ascendant—the sign rising on the eastern horizon at the moment of birth—is of central importance. By comparison, the Sun sign emphasized in Western Astrology carries relatively little significance.` } },
      { type: "paragraph", text: { en: `The Ascendant plays a crucial role in determining suitable planetary remedies within Jyotish. It is also essential because it establishes which planets function as benefics and which act as malefics for a particular individual.`, ja: `The Ascendant plays a crucial role in determining suitable planetary remedies within Jyotish. It is also essential because it establishes which planets function as benefics and which act as malefics for a particular individual.` } },
      { type: "heading", level: 3, text: { en: `Jyotish Always Uses the Sidereal Zodiac`, ja: `Jyotish Always Uses the Sidereal Zodiac` } },
      { type: "paragraph", text: { en: `Jyotish employs the same twelve zodiac signs used in Western Astrology. The difference lies in the reference point.`, ja: `Jyotish employs the same twelve zodiac signs used in Western Astrology. The difference lies in the reference point.` } },
      { type: "paragraph", text: { en: `In Jyotish, the zodiac is permanently aligned with the fixed stars and therefore remains stationary. This is known as the Sidereal Zodiac. Western Astrology, by contrast, generally uses the Tropical Zodiac, which gradually shifts over time.`, ja: `In Jyotish, the zodiac is permanently aligned with the fixed stars and therefore remains stationary. This is known as the Sidereal Zodiac. Western Astrology, by contrast, generally uses the Tropical Zodiac, which gradually shifts over time.` } },
      { type: "paragraph", text: { en: `As a result, planetary positions are often different in the two systems, and planets may appear in different signs depending on which zodiac is being used.`, ja: `As a result, planetary positions are often different in the two systems, and planets may appear in different signs depending on which zodiac is being used.` } },
      { type: "paragraph", text: { en: `Many Western Astrologers may find it surprising that the Tropical Zodiac is referenced to the moving equinox points rather than the fixed stars. Since these equinox points slowly shift relative to the background of the stars, the Tropical Zodiac itself gradually moves through the sky.`, ja: `Many Western Astrologers may find it surprising that the Tropical Zodiac is referenced to the moving equinox points rather than the fixed stars. Since these equinox points slowly shift relative to the background of the stars, the Tropical Zodiac itself gradually moves through the sky.` } },
      { type: "paragraph", text: { en: `This means that the section of the zodiac called "Aries" in the Western system is not permanently tied to a specific stellar constellation. Over long periods, its position changes. The angular separation between the starting points of the Tropical and Sidereal zodiacs—currently around 24 degrees—is known as the Ayanamsha.`, ja: `This means that the section of the zodiac called "Aries" in the Western system is not permanently tied to a specific stellar constellation. Over long periods, its position changes. The angular separation between the starting points of the Tropical and Sidereal zodiacs—currently around 24 degrees—is known as the Ayanamsha.` } },
      { type: "paragraph", text: { en: `Traditional Jyotish also employs the equal-house concept, where each house spans 30 degrees and corresponds directly with a sign in the Sidereal Zodiac. Western Astrology frequently uses unequal house division systems.`, ja: `Traditional Jyotish also employs the equal-house concept, where each house spans 30 degrees and corresponds directly with a sign in the Sidereal Zodiac. Western Astrology frequently uses unequal house division systems.` } },
      { type: "heading", level: 3, text: { en: `Jyotish Uses ‘Functional Benefics’ and ‘Functional Malefics’`, ja: `Jyotish Uses ‘Functional Benefics’ and ‘Functional Malefics’` } },
      { type: "paragraph", text: { en: `Beyond their natural benefic or malefic tendencies, planets in Jyotish acquire additional characteristics based on the houses they own or rule within an individual's birth chart. Western Astrology has no direct equivalent to this concept.`, ja: `Beyond their natural benefic or malefic tendencies, planets in Jyotish acquire additional characteristics based on the houses they own or rule within an individual's birth chart. Western Astrology has no direct equivalent to this concept.` } },
      { type: "paragraph", text: { en: `For instance, Mars—naturally considered a malefic planet—can become an exceptionally positive influence for someone with a Leo (Sidereal) Ascendant. Conversely, Venus, generally regarded as a natural benefic, can become quite unfavorable for a person with a Pisces (Sidereal) Ascendant.`, ja: `For instance, Mars—naturally considered a malefic planet—can become an exceptionally positive influence for someone with a Leo (Sidereal) Ascendant. Conversely, Venus, generally regarded as a natural benefic, can become quite unfavorable for a person with a Pisces (Sidereal) Ascendant.` } },
      { type: "paragraph", text: { en: `This principle is essential for accurate chart interpretation and for prescribing planetary remedies, including the recommendation of gemstones.`, ja: `This principle is essential for accurate chart interpretation and for prescribing planetary remedies, including the recommendation of gemstones.` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `Footnotes` } },
      { type: "paragraph", text: { en: `[1] Jyotish addresses predictions relating to the four primary areas of life described in the Vedas: Artha, Dharma, Kama, and Moksha.`, ja: `[1] Jyotish addresses predictions relating to the four primary areas of life described in the Vedas: Artha, Dharma, Kama, and Moksha.` } },
      { type: "paragraph", text: { en: `• Artha relates to wealth in its broadest sense, including money, prosperity, children, knowledge, food, and health.`, ja: `• Artha relates to wealth in its broadest sense, including money, prosperity, children, knowledge, food, and health.` } },
      { type: "paragraph", text: { en: `• Dharma concerns duty, character, righteous action, and activities that support evolution and alignment with natural law, including career and life purpose.`, ja: `• Dharma concerns duty, character, righteous action, and activities that support evolution and alignment with natural law, including career and life purpose.` } },
      { type: "paragraph", text: { en: `• Kama refers to desire and therefore encompasses relationships, sensory pleasures, ambitions, and personal aspirations.`, ja: `• Kama refers to desire and therefore encompasses relationships, sensory pleasures, ambitions, and personal aspirations.` } },
      { type: "paragraph", text: { en: `• Moksha relates to spiritual growth, inner development, and progress toward Self-realization.`, ja: `• Moksha relates to spiritual growth, inner development, and progress toward Self-realization.` } },
    ],
  },
  {
    id: "paradigm-shift",
    section: "introduction",
    title: { en: `Vedic Astrology – A Paradigm Shift`, ja: `Vedic Astrology – A Paradigm Shift` },
    related: ["western-differences","planetary-forces","origins-of-jyotish"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Vedic Astrology – A Paradigm Shift`, ja: `Vedic Astrology – A Paradigm Shift` } },
      { type: "paragraph", text: { en: `Summary: This article explores the paradigm shift required for Western Astrologers to understand the fundamental principles that underpin the predictive and preventive system of Vedic Astrology. These principles include concepts such as reincarnation, karma, planetary arrangements as coded information, the possibility of modifying returning karma, and the understanding that consciousness itself is the ultimate reality.`, ja: `Summary: This article explores the paradigm shift required for Western Astrologers to understand the fundamental principles that underpin the predictive and preventive system of Vedic Astrology. These principles include concepts such as reincarnation, karma, planetary arrangements as coded information, the possibility of modifying returning karma, and the understanding that consciousness itself is the ultimate reality.` } },
      { type: "heading", level: 3, text: { en: `Jyotish – A Major Paradigm Shift for Western Astrologers`, ja: `Jyotish – A Major Paradigm Shift for Western Astrologers` } },
      { type: "paragraph", text: { en: `A Self-realized Vedic Master and universal Guru once made the following profound statement regarding Vedic Astrology:`, ja: `A Self-realized Vedic Master and universal Guru once made the following profound statement regarding Vedic Astrology:` } },
      { type: "paragraph", text: { en: `“The purpose of astrology is to take you to the ultimate truth that the entire universe is one organism. It’s one Being, one consciousness, one Self, that manifests itself into this varied universe.” [1]`, ja: `“The purpose of astrology is to take you to the ultimate truth that the entire universe is one organism. It’s one Being, one consciousness, one Self, that manifests itself into this varied universe.” [1]` } },
      { type: "paragraph", text: { en: `Similar perspectives are shared by Masters from many spiritual traditions, including Buddhist, Taoist, Tantric, Yogic, and others. These views arise from direct experiential knowledge gained through higher states of consciousness.`, ja: `Similar perspectives are shared by Masters from many spiritual traditions, including Buddhist, Taoist, Tantric, Yogic, and others. These views arise from direct experiential knowledge gained through higher states of consciousness.` } },
      { type: "paragraph", text: { en: `It is worthwhile reflecting on the astrological implications of this statement. It suggests that the ultimate reality is not matter or energy, but consciousness itself. At its deepest level, Vedic Astrology therefore deals with a field of information that emerges from universal consciousness.`, ja: `It is worthwhile reflecting on the astrological implications of this statement. It suggests that the ultimate reality is not matter or energy, but consciousness itself. At its deepest level, Vedic Astrology therefore deals with a field of information that emerges from universal consciousness.` } },
      { type: "paragraph", text: { en: `To fully appreciate where Jyotish originates from, a significant shift in perspective is often required for astrologers who have been educated within Western astrological frameworks.`, ja: `To fully appreciate where Jyotish originates from, a significant shift in perspective is often required for astrologers who have been educated within Western astrological frameworks.` } },
      { type: "heading", level: 3, text: { en: `Some Examples of Major Paradigm Shifts`, ja: `Some Examples of Major Paradigm Shifts` } },
      { type: "paragraph", text: { en: `Below are a few examples of paradigm shifts that dramatically changed humanity’s understanding of reality. If you are already familiar with these examples, you may wish to proceed directly to the section: “Paradigm Changing Concepts in Jyotish Astrology.”`, ja: `Below are a few examples of paradigm shifts that dramatically changed humanity’s understanding of reality. If you are already familiar with these examples, you may wish to proceed directly to the section: “Paradigm Changing Concepts in Jyotish Astrology.”` } },
      { type: "heading", level: 3, text: { en: `Shift from ‘Flat-Earth’ to Heliocentric Viewpoint`, ja: `Shift from ‘Flat-Earth’ to Heliocentric Viewpoint` } },
      { type: "paragraph", text: { en: `For centuries, humanity believed that the Sun and planets revolved around the Earth, and that the Earth itself occupied the centre of the universe. These ideas became deeply embedded within society and formed a conceptual framework that shaped the way people viewed reality. The scholars and institutions of the time, particularly the Church, strongly supported these beliefs.`, ja: `For centuries, humanity believed that the Sun and planets revolved around the Earth, and that the Earth itself occupied the centre of the universe. These ideas became deeply embedded within society and formed a conceptual framework that shaped the way people viewed reality. The scholars and institutions of the time, particularly the Church, strongly supported these beliefs.` } },
      { type: "paragraph", text: { en: `Eventually, overwhelming scientific evidence emerged showing that what had once been regarded as self-evident truth was simply the result of an Earth-centred perspective. Contrary to appearances, the Earth and planets revolve around the Sun.`, ja: `Eventually, overwhelming scientific evidence emerged showing that what had once been regarded as self-evident truth was simply the result of an Earth-centred perspective. Contrary to appearances, the Earth and planets revolve around the Sun.` } },
      { type: "paragraph", text: { en: `Looking back today, it can be difficult to appreciate the upheaval caused by this change in understanding, or why supporters of the new viewpoint were labelled heretics. It is equally difficult to understand why the old ideas persisted for so long. This serves as one example of a major paradigm shift. There are many others.`, ja: `Looking back today, it can be difficult to appreciate the upheaval caused by this change in understanding, or why supporters of the new viewpoint were labelled heretics. It is equally difficult to understand why the old ideas persisted for so long. This serves as one example of a major paradigm shift. There are many others.` } },
      { type: "heading", level: 3, text: { en: `Shift from ‘Created’ to ‘Evolved’ Viewpoint`, ja: `Shift from ‘Created’ to ‘Evolved’ Viewpoint` } },
      { type: "paragraph", text: { en: `More recently, the concept of biological evolution challenged the long-established belief that God created all life forms exactly as they exist today and that no change was possible within the divine plan.`, ja: `More recently, the concept of biological evolution challenged the long-established belief that God created all life forms exactly as they exist today and that no change was possible within the divine plan.` } },
      { type: "paragraph", text: { en: `What began as a theory eventually became accepted fact when scientific methods enabled the dating of fossils, many of which were found to be hundreds of millions or even billions of years old. Although some religious fundamentalists continue to believe that everything was created only a few thousand years ago, evolutionary theory fundamentally transformed our understanding of life on Earth.`, ja: `What began as a theory eventually became accepted fact when scientific methods enabled the dating of fossils, many of which were found to be hundreds of millions or even billions of years old. Although some religious fundamentalists continue to believe that everything was created only a few thousand years ago, evolutionary theory fundamentally transformed our understanding of life on Earth.` } },
      { type: "heading", level: 3, text: { en: `Shift from Newtonian Mechanistic to Quantum Understandings`, ja: `Shift from Newtonian Mechanistic to Quantum Understandings` } },
      { type: "paragraph", text: { en: `Another major paradigm shift occurred in physics. The laws of motion developed by Isaac Newton proved insufficient to explain all observed phenomena, particularly those involving subatomic particles or objects travelling near the speed of light.`, ja: `Another major paradigm shift occurred in physics. The laws of motion developed by Isaac Newton proved insufficient to explain all observed phenomena, particularly those involving subatomic particles or objects travelling near the speed of light.` } },
      { type: "paragraph", text: { en: `This led to the development of Einstein’s theory of relativity and the emergence of quantum physics. As with all major shifts in understanding, acceptance was gradual. Significant changes in worldview often require time before they become widely integrated into public consciousness. As the saying goes, “Paradigm shifts usually occur one funeral at a time.”`, ja: `This led to the development of Einstein’s theory of relativity and the emergence of quantum physics. As with all major shifts in understanding, acceptance was gradual. Significant changes in worldview often require time before they become widely integrated into public consciousness. As the saying goes, “Paradigm shifts usually occur one funeral at a time.”` } },
      { type: "heading", level: 3, text: { en: `Paradigm Changing Concepts in Jyotish Astrology`, ja: `Paradigm Changing Concepts in Jyotish Astrology` } },
      { type: "heading", level: 3, text: { en: `1. Planets Do Not Affect People`, ja: `1. Planets Do Not Affect People` } },
      { type: "paragraph", text: { en: `A Jyotish Astrologer understands that planets do not affect people—it is people who affect people.`, ja: `A Jyotish Astrologer understands that planets do not affect people—it is people who affect people.` } },
      { type: "paragraph", text: { en: `Within Western Astrology, it is easy to adopt what might be called an "astrological victim consciousness." For example, someone may say: “I’m going through a difficult period because of my Saturn transit.” This implies that Saturn is somehow responsible for the hardships being experienced.`, ja: `Within Western Astrology, it is easy to adopt what might be called an "astrological victim consciousness." For example, someone may say: “I’m going through a difficult period because of my Saturn transit.” This implies that Saturn is somehow responsible for the hardships being experienced.` } },
      { type: "paragraph", text: { en: `Jyotish rejects this idea. It teaches that any condition or circumstance we experience is the result of our own past thoughts, words, and actions.`, ja: `Jyotish rejects this idea. It teaches that any condition or circumstance we experience is the result of our own past thoughts, words, and actions.` } },
      { type: "paragraph", text: { en: `A common response might be: “I cannot remember doing anything that would produce what I am currently experiencing.”`, ja: `A common response might be: “I cannot remember doing anything that would produce what I am currently experiencing.”` } },
      { type: "paragraph", text: { en: `From the Jyotish perspective, the answer is straightforward. Our memory simply does not extend far enough back. To fully understand our present circumstances, we may need access to memories stretching across many lifetimes.`, ja: `From the Jyotish perspective, the answer is straightforward. Our memory simply does not extend far enough back. To fully understand our present circumstances, we may need access to memories stretching across many lifetimes.` } },
      { type: "paragraph", text: { en: `For this reason, Jyotish incorporates the principles of reincarnation and karma—the return of the fruits of past actions.`, ja: `For this reason, Jyotish incorporates the principles of reincarnation and karma—the return of the fruits of past actions.` } },
      { type: "paragraph", text: { en: `At its most fundamental level, the mechanics of Jyotish rely upon the Vedic Model of Reality, which views the universe and all beings within it as parts of one interconnected whole.`, ja: `At its most fundamental level, the mechanics of Jyotish rely upon the Vedic Model of Reality, which views the universe and all beings within it as parts of one interconnected whole.` } },
      { type: "heading", level: 3, text: { en: `2. We Were Not Born at a Particular Time Merely by Chance`, ja: `2. We Were Not Born at a Particular Time Merely by Chance` } },
      { type: "paragraph", text: { en: `According to Jyotish, we were not born at a specific moment with a particular planetary arrangement merely by accident.`, ja: `According to Jyotish, we were not born at a specific moment with a particular planetary arrangement merely by accident.` } },
      { type: "paragraph", text: { en: `The Vedic tradition does not subscribe to the idea that the Creator plays dice. It would seem inherently unfair if some individuals were born into wealthy families while others entered lives of extreme hardship purely through chance.`, ja: `The Vedic tradition does not subscribe to the idea that the Creator plays dice. It would seem inherently unfair if some individuals were born into wealthy families while others entered lives of extreme hardship purely through chance.` } },
      { type: "paragraph", text: { en: `Jyotish suggests that our birth time and place are determined by our past karmas and latent impressions, known as samskaras.`, ja: `Jyotish suggests that our birth time and place are determined by our past karmas and latent impressions, known as samskaras.` } },
      { type: "paragraph", text: { en: `The arrangement of the nine planets, together with their future transits through the twelve houses and twenty-seven Nakshatras, reflects how our life will unfold as a consequence of past actions. The moment of incarnation therefore mirrors the karmic lessons required for our evolution.`, ja: `The arrangement of the nine planets, together with their future transits through the twelve houses and twenty-seven Nakshatras, reflects how our life will unfold as a consequence of past actions. The moment of incarnation therefore mirrors the karmic lessons required for our evolution.` } },
      { type: "paragraph", text: { en: `Through this celestial blueprint, Jyotish can identify both the benefits and challenges likely to arise, as well as the timing of their manifestation.`, ja: `Through this celestial blueprint, Jyotish can identify both the benefits and challenges likely to arise, as well as the timing of their manifestation.` } },
      { type: "heading", level: 3, text: { en: `3. Planets Don’t Emit a Physical ‘Force’ that Affects People`, ja: `3. Planets Don’t Emit a Physical ‘Force’ that Affects People` } },
      { type: "paragraph", text: { en: `Many Western Astrologers believe that planets emit some form of force that influences human life, even though science has not yet identified such a force.`, ja: `Many Western Astrologers believe that planets emit some form of force that influences human life, even though science has not yet identified such a force.` } },
      { type: "paragraph", text: { en: `This concept is essentially mechanistic and rooted in a Newtonian model of reality.`, ja: `This concept is essentially mechanistic and rooted in a Newtonian model of reality.` } },
      { type: "paragraph", text: { en: `Vedic Astrology takes a different view. It sees planetary arrangements as information rather than physical or hidden esoteric forces. The positions of the planets at birth form a code that can be interpreted by a skilled Jyotish Astrologer and translated into meaningful predictions.`, ja: `Vedic Astrology takes a different view. It sees planetary arrangements as information rather than physical or hidden esoteric forces. The positions of the planets at birth form a code that can be interpreted by a skilled Jyotish Astrologer and translated into meaningful predictions.` } },
      { type: "paragraph", text: { en: `Jyotish also makes extensive use of Rahu and Ketu, the Moon’s nodes. These are not physical objects at all. They are mathematical points created where the Moon’s orbit intersects the ecliptic.`, ja: `Jyotish also makes extensive use of Rahu and Ketu, the Moon’s nodes. These are not physical objects at all. They are mathematical points created where the Moon’s orbit intersects the ecliptic.` } },
      { type: "paragraph", text: { en: `Since Rahu and Ketu have no material existence, they clearly cannot exert a physical force. Yet they are associated with powerful karmic effects and significant life events.`, ja: `Since Rahu and Ketu have no material existence, they clearly cannot exert a physical force. Yet they are associated with powerful karmic effects and significant life events.` } },
      { type: "paragraph", text: { en: `Further support for this information-based model comes from the fact that planetary effects vary dramatically according to an individual's Ascendant.[2] There is no direct equivalent of this concept in Western Astrology.`, ja: `Further support for this information-based model comes from the fact that planetary effects vary dramatically according to an individual's Ascendant.[2] There is no direct equivalent of this concept in Western Astrology.` } },
      { type: "heading", level: 3, text: { en: `4. Jyotish Has No Need to Use Neptune, Uranus, Pluto or Asteroids`, ja: `4. Jyotish Has No Need to Use Neptune, Uranus, Pluto or Asteroids` } },
      { type: "paragraph", text: { en: `Many Western Astrologers assume that Jyotish is limited because it does not incorporate Neptune, Uranus, Pluto, or asteroids into its calculations.`, ja: `Many Western Astrologers assume that Jyotish is limited because it does not incorporate Neptune, Uranus, Pluto, or asteroids into its calculations.` } },
      { type: "paragraph", text: { en: `However, Jyotish does not regard this as a limitation.`, ja: `However, Jyotish does not regard this as a limitation.` } },
      { type: "paragraph", text: { en: `The positions of the seven visible planets, together with the Moon’s two nodes, across the twelve signs, twelve houses, and twenty-seven Nakshatras already provide a highly sophisticated system of encoded information.`, ja: `The positions of the seven visible planets, together with the Moon’s two nodes, across the twelve signs, twelve houses, and twenty-seven Nakshatras already provide a highly sophisticated system of encoded information.` } },
      { type: "paragraph", text: { en: `Combined with transit analysis, this arrangement contains all the information necessary to understand the key areas of life: Artha, Dharma, Kama, and Moksha.[3]`, ja: `Combined with transit analysis, this arrangement contains all the information necessary to understand the key areas of life: Artha, Dharma, Kama, and Moksha.[3]` } },
      { type: "paragraph", text: { en: `Jyotish also uses the Moon’s position to determine major life periods known as Mahadashas, through which karmic results are delivered by the nine planets.`, ja: `Jyotish also uses the Moon’s position to determine major life periods known as Mahadashas, through which karmic results are delivered by the nine planets.` } },
      { type: "paragraph", text: { en: `As a result, there is no requirement to include Neptune, Uranus, Pluto, or asteroids in order to make accurate and meaningful predictions.`, ja: `As a result, there is no requirement to include Neptune, Uranus, Pluto, or asteroids in order to make accurate and meaningful predictions.` } },
      { type: "heading", level: 3, text: { en: `5. Jyotish Provides Remedial Measures to Modify Returning Karmas`, ja: `5. Jyotish Provides Remedial Measures to Modify Returning Karmas` } },
      { type: "paragraph", text: { en: `Since all beings are viewed as part of an interconnected whole, participation in certain Vedic practices can influence returning karmas.`, ja: `Since all beings are viewed as part of an interconnected whole, participation in certain Vedic practices can influence returning karmas.` } },
      { type: "paragraph", text: { en: `These may include prescribed acts of charity, specific Vedic ceremonies, the recitation of Sanskrit mantras, or the wearing of appropriate gemstones.`, ja: `These may include prescribed acts of charity, specific Vedic ceremonies, the recitation of Sanskrit mantras, or the wearing of appropriate gemstones.` } },
      { type: "paragraph", text: { en: `Such methods are commonly referred to as Planetary Antidotes or Remedial Measures.`, ja: `Such methods are commonly referred to as Planetary Antidotes or Remedial Measures.` } },
      { type: "paragraph", text: { en: `Jyotish therefore offers the ability not only to identify returning karmas, but also to reduce, modify, or redirect their effects.[4]`, ja: `Jyotish therefore offers the ability not only to identify returning karmas, but also to reduce, modify, or redirect their effects.[4]` } },
      { type: "heading", level: 3, text: { en: `6. Jyotish Astrology Came from G.O.D.`, ja: `6. Jyotish Astrology Came from G.O.D.` } },
      { type: "paragraph", text: { en: `If you ask a Jyotish Astrologer about the origins of their discipline, they are likely to tell you that it came from G.O.D.`, ja: `If you ask a Jyotish Astrologer about the origins of their discipline, they are likely to tell you that it came from G.O.D.` } },
      { type: "paragraph", text: { en: `Here, G.O.D. stands for Generator, Operator and Destroyer, represented in the Vedic tradition by Brahma, Vishnu, and Shiva.`, ja: `Here, G.O.D. stands for Generator, Operator and Destroyer, represented in the Vedic tradition by Brahma, Vishnu, and Shiva.` } },
      { type: "paragraph", text: { en: `This concept represents a major distinction between Jyotish and Western Astrology.`, ja: `This concept represents a major distinction between Jyotish and Western Astrology.` } },
      { type: "paragraph", text: { en: `According to tradition, the knowledge of Jyotish was revealed or cognized. It was not invented, experimentally developed, or gradually refined over centuries by human beings.`, ja: `According to tradition, the knowledge of Jyotish was revealed or cognized. It was not invented, experimentally developed, or gradually refined over centuries by human beings.` } },
      { type: "paragraph", text: { en: `Western thought offers no exact equivalent to this process. However, the same mechanism is also said to be responsible for the emergence of other Applied Vedic Sciences such as Ayurveda and Vastu.`, ja: `Western thought offers no exact equivalent to this process. However, the same mechanism is also said to be responsible for the emergence of other Applied Vedic Sciences such as Ayurveda and Vastu.` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `Footnotes` } },
      { type: "paragraph", text: { en: `[1] Sri Sri Ravi Shankar: The Daily Sutra (Art of Living Foundation – Indian NGO), 20th May 2003.`, ja: `[1] Sri Sri Ravi Shankar: The Daily Sutra (Art of Living Foundation – Indian NGO), 20th May 2003.` } },
      { type: "paragraph", text: { en: `[2] For example, in Jyotish, Mars is generally highly beneficial for a person with a Leo Ascendant, while often producing strongly challenging effects for someone with a Virgo Ascendant. Thus the same planet can signify positive outcomes for one individual and negative outcomes for another. This strongly suggests that we are dealing with an integrated field of information rather than a physical force emanating from the planet itself.`, ja: `[2] For example, in Jyotish, Mars is generally highly beneficial for a person with a Leo Ascendant, while often producing strongly challenging effects for someone with a Virgo Ascendant. Thus the same planet can signify positive outcomes for one individual and negative outcomes for another. This strongly suggests that we are dealing with an integrated field of information rather than a physical force emanating from the planet itself.` } },
      { type: "paragraph", text: { en: `[3] Artha relates to wealth and prosperity in all forms, including money, children, knowledge, food, and health. Dharma concerns duty, character, right action, and activities aligned with natural law. Kama encompasses desire, relationships, sensory pleasures, and aspirations. Moksha relates to spiritual development and progress toward Self-realization.`, ja: `[3] Artha relates to wealth and prosperity in all forms, including money, children, knowledge, food, and health. Dharma concerns duty, character, right action, and activities aligned with natural law. Kama encompasses desire, relationships, sensory pleasures, and aspirations. Moksha relates to spiritual development and progress toward Self-realization.` } },
      { type: "paragraph", text: { en: `[4] Vedic ceremonies such as Yagnas, when performed correctly by enlightened pundits, are believed to alter returning karmas. Likewise, because the universe is regarded as an interconnected whole, gemstones associated with particular planets and Sanskrit mantras are considered effective methods for modifying karmic influences and harmonizing the laws of nature.`, ja: `[4] Vedic ceremonies such as Yagnas, when performed correctly by enlightened pundits, are believed to alter returning karmas. Likewise, because the universe is regarded as an interconnected whole, gemstones associated with particular planets and Sanskrit mantras are considered effective methods for modifying karmic influences and harmonizing the laws of nature.` } },
    ],
  },
  {
    id: "sidereal-zodiac-p3",
    section: "introduction",
    title: { en: `Jyotish – Sidereal Zodiac`, ja: `Jyotish – Sidereal Zodiac` },
    related: ["nakshatras-stellar-1","western-differences","key-differences-intro"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Sidereal Zodiac`, ja: `Jyotish – Sidereal Zodiac` } },
      { type: "paragraph", text: { en: `Summary: This article explores the differences between the zodiacs used in Vedic Astrology and Western Astrology. It explains why Jyotish relies on the fixed Sidereal Zodiac rather than the movable Tropical Zodiac. In doing so, it addresses one of the primary objections astronomers raise against astrology. The article also demonstrates how Sun signs, Ascendants, and all planetary positions can appear in different signs when calculated using the two systems.`, ja: `Summary: This article explores the differences between the zodiacs used in Vedic Astrology and Western Astrology. It explains why Jyotish relies on the fixed Sidereal Zodiac rather than the movable Tropical Zodiac. In doing so, it addresses one of the primary objections astronomers raise against astrology. The article also demonstrates how Sun signs, Ascendants, and all planetary positions can appear in different signs when calculated using the two systems.` } },
      { type: "heading", level: 3, text: { en: `Jyotish Uses the Fixed Sidereal Zodiac`, ja: `Jyotish Uses the Fixed Sidereal Zodiac` } },
      { type: "paragraph", text: { en: `Jyotish Astrology uses a different zodiac from the one employed in Western Astrology.`, ja: `Jyotish Astrology uses a different zodiac from the one employed in Western Astrology.` } },
      { type: "paragraph", text: { en: `The zodiacs used by both Jyotish and Western Astrology are based upon an imaginary celestial sphere. In each system, this sphere is divided into twelve equal sections of 30 degrees each, much like the segments of an orange. Both systems also use the same zodiac sign names, such as Aries, Taurus, Gemini, and so forth. The Sun appears to move through each zodiac sign in approximately one month.`, ja: `The zodiacs used by both Jyotish and Western Astrology are based upon an imaginary celestial sphere. In each system, this sphere is divided into twelve equal sections of 30 degrees each, much like the segments of an orange. Both systems also use the same zodiac sign names, such as Aries, Taurus, Gemini, and so forth. The Sun appears to move through each zodiac sign in approximately one month.` } },
      { type: "paragraph", text: { en: `Jyotish uses the fixed Sidereal Zodiac. The term Sidereal means "with respect to the stars." The starting point of the Sidereal Zodiac is permanently anchored using the background of the fixed stars within our galaxy as its reference point.[1] As a result, the zodiac signs remain forever fixed relative to the stellar constellations.`, ja: `Jyotish uses the fixed Sidereal Zodiac. The term Sidereal means "with respect to the stars." The starting point of the Sidereal Zodiac is permanently anchored using the background of the fixed stars within our galaxy as its reference point.[1] As a result, the zodiac signs remain forever fixed relative to the stellar constellations.` } },
      { type: "paragraph", text: { en: `Therefore, in Vedic Astrology, the beginning of the first sign, Aries, never changes position. Since Aries remains fixed, all of the remaining zodiac signs also stay permanently aligned with the distant background stars.`, ja: `Therefore, in Vedic Astrology, the beginning of the first sign, Aries, never changes position. Since Aries remains fixed, all of the remaining zodiac signs also stay permanently aligned with the distant background stars.` } },
      { type: "paragraph", text: { en: `Western Astrology, by contrast, uses the movable Tropical Zodiac. The starting point of this zodiac gradually shifts relative to the background of the fixed stars because it is referenced to the equinox. This movement occurs due to the astronomical phenomenon known as the precession of the equinoxes.[2]`, ja: `Western Astrology, by contrast, uses the movable Tropical Zodiac. The starting point of this zodiac gradually shifts relative to the background of the fixed stars because it is referenced to the equinox. This movement occurs due to the astronomical phenomenon known as the precession of the equinoxes.[2]` } },
      { type: "paragraph", text: { en: `Consequently, in Western Astrology, the position associated with the sign Aries slowly moves through the sky against the background of the fixed stars. It is therefore not permanently linked to any specific stellar constellation. Many people—including students of Western Astrology—find this fact quite surprising.`, ja: `Consequently, in Western Astrology, the position associated with the sign Aries slowly moves through the sky against the background of the fixed stars. It is therefore not permanently linked to any specific stellar constellation. Many people—including students of Western Astrology—find this fact quite surprising.` } },
      { type: "paragraph", text: { en: `Astronomers often criticize Western Astrology because it employs the movable Tropical Zodiac, meaning that the sign Aries changes its position relative to the stars over time. However, this criticism does not apply to Jyotish because Vedic Astrology uses a fixed zodiac rather than a moving one.`, ja: `Astronomers often criticize Western Astrology because it employs the movable Tropical Zodiac, meaning that the sign Aries changes its position relative to the stars over time. However, this criticism does not apply to Jyotish because Vedic Astrology uses a fixed zodiac rather than a moving one.` } },
      { type: "heading", level: 3, text: { en: `Ayanamsa – Angular Difference Between the Two Zodiacs`, ja: `Ayanamsa – Angular Difference Between the Two Zodiacs` } },
      { type: "paragraph", text: { en: `The angular difference between the Sidereal and Tropical zodiacs is known as the Ayanamsa (ayanāṃśa or ayanamsha), and this difference gradually increases over time.[3]`, ja: `The angular difference between the Sidereal and Tropical zodiacs is known as the Ayanamsa (ayanāṃśa or ayanamsha), and this difference gradually increases over time.[3]` } },
      { type: "paragraph", text: { en: `Although the starting points of the two zodiacs were approximately aligned around 1,700 years ago, the Tropical Zodiac used in Western Astrology has steadily moved away from that original position.`, ja: `Although the starting points of the two zodiacs were approximately aligned around 1,700 years ago, the Tropical Zodiac used in Western Astrology has steadily moved away from that original position.` } },
      { type: "paragraph", text: { en: `As of 2021, the difference between the two systems is approximately 24 degrees. This means that if the Sun is positioned at 29 degrees Virgo in the Tropical Zodiac, it will appear at approximately 5 degrees Virgo in the Sidereal Zodiac after subtracting the 24-degree Ayanamsa.`, ja: `As of 2021, the difference between the two systems is approximately 24 degrees. This means that if the Sun is positioned at 29 degrees Virgo in the Tropical Zodiac, it will appear at approximately 5 degrees Virgo in the Sidereal Zodiac after subtracting the 24-degree Ayanamsa.` } },
      { type: "paragraph", text: { en: `In this example, the Sun remains in Virgo in both systems.`, ja: `In this example, the Sun remains in Virgo in both systems.` } },
      { type: "paragraph", text: { en: `However, if the Sun is located between 0 and 24 degrees Virgo in the Tropical Zodiac, it will move into Leo when calculated using the Sidereal Zodiac employed by Jyotish. In effect, the planet shifts backward (anti-clockwise) by the Ayanamsa value and enters the previous sign.[4]`, ja: `However, if the Sun is located between 0 and 24 degrees Virgo in the Tropical Zodiac, it will move into Leo when calculated using the Sidereal Zodiac employed by Jyotish. In effect, the planet shifts backward (anti-clockwise) by the Ayanamsa value and enters the previous sign.[4]` } },
      { type: "paragraph", text: { en: `As a result, a person's Sun sign may differ depending on which zodiac is used. For example, an individual classified as a Virgo in Western Astrology may become a Leo in Jyotish.`, ja: `As a result, a person's Sun sign may differ depending on which zodiac is used. For example, an individual classified as a Virgo in Western Astrology may become a Leo in Jyotish.` } },
      { type: "paragraph", text: { en: `The same principle applies not only to the Sun but also to all other planets and to the Ascendant. These differences in planetary and Ascendant placements help explain many of the inconsistencies sometimes encountered in charts interpreted solely through the modern Western system.`, ja: `The same principle applies not only to the Sun but also to all other planets and to the Ascendant. These differences in planetary and Ascendant placements help explain many of the inconsistencies sometimes encountered in charts interpreted solely through the modern Western system.` } },
      { type: "heading", level: 3, text: { en: `Nakshatras – ‘Stellar Constellations’`, ja: `Nakshatras – ‘Stellar Constellations’` } },
      { type: "paragraph", text: { en: `Jyotish places considerable importance on the Nakshatras, or stellar constellations, when interpreting birth charts, assessing compatibility, and determining auspicious timing through Muhurta.`, ja: `Jyotish places considerable importance on the Nakshatras, or stellar constellations, when interpreting birth charts, assessing compatibility, and determining auspicious timing through Muhurta.` } },
      { type: "paragraph", text: { en: `There are twenty-seven Nakshatras, sometimes referred to as Lunar Mansions, distributed evenly throughout the zodiac (more precisely, as equal divisions along the ecliptic).`, ja: `There are twenty-seven Nakshatras, sometimes referred to as Lunar Mansions, distributed evenly throughout the zodiac (more precisely, as equal divisions along the ecliptic).` } },
      { type: "paragraph", text: { en: `Given the importance of the Nakshatras within Jyotish, it is hardly surprising that Vedic Astrology uses a zodiac that remains permanently aligned with both the fixed stars and the Nakshatra system.`, ja: `Given the importance of the Nakshatras within Jyotish, it is hardly surprising that Vedic Astrology uses a zodiac that remains permanently aligned with both the fixed stars and the Nakshatra system.` } },
      { type: "heading", level: 3, text: { en: `Footnotes`, ja: `Footnotes` } },
      { type: "paragraph", text: { en: `[1] The so-called "fixed stars" are located at such immense distances from Earth that their angular movement relative to our Sun is extremely small, even across thousands of years. For practical purposes, they can therefore be regarded as fixed or immovable reference points.`, ja: `[1] The so-called "fixed stars" are located at such immense distances from Earth that their angular movement relative to our Sun is extremely small, even across thousands of years. For practical purposes, they can therefore be regarded as fixed or immovable reference points.` } },
      { type: "paragraph", text: { en: `[2] The equinox point on Earth's orbit around the Sun shifts relative to the background of the fixed stars because of the phenomenon known as the precession of the equinoxes. This occurs due to a slight wobble in Earth's rotational axis, similar to the motion of a spinning top whose axis slowly traces out a cone-shaped path. One complete precessional cycle takes approximately 26,000 years.`, ja: `[2] The equinox point on Earth's orbit around the Sun shifts relative to the background of the fixed stars because of the phenomenon known as the precession of the equinoxes. This occurs due to a slight wobble in Earth's rotational axis, similar to the motion of a spinning top whose axis slowly traces out a cone-shaped path. One complete precessional cycle takes approximately 26,000 years.` } },
      { type: "paragraph", text: { en: `[3] As of 2021, the angular separation between the Tropical and Sidereal zodiacs is approximately 24 degrees. This value, derived by Lahiri, is widely accepted among Jyotish Astrologers, and most astrological tables use Lahiri Ayanamsa. The Tropical Zodiac moves relative to the Sidereal Zodiac by roughly one degree every 71 years. Although this annual shift is small, it accumulates significantly over long periods. Remarkably, ancient Egyptian astronomers observed this movement thousands of years ago.`, ja: `[3] As of 2021, the angular separation between the Tropical and Sidereal zodiacs is approximately 24 degrees. This value, derived by Lahiri, is widely accepted among Jyotish Astrologers, and most astrological tables use Lahiri Ayanamsa. The Tropical Zodiac moves relative to the Sidereal Zodiac by roughly one degree every 71 years. Although this annual shift is small, it accumulates significantly over long periods. Remarkably, ancient Egyptian astronomers observed this movement thousands of years ago.` } },
      { type: "paragraph", text: { en: `[4] The current difference between the two zodiacs is approximately 24 degrees. For example, if the Sun is positioned at 14 degrees Virgo in Western Astrology, subtracting the Ayanamsa gives 14 – 24 = –10 degrees Virgo in the Sidereal system. Since this falls before the beginning of Virgo, the Sun effectively moves backward into Leo and occupies 20 degrees Leo (–10 + 30 = 20).`, ja: `[4] The current difference between the two zodiacs is approximately 24 degrees. For example, if the Sun is positioned at 14 degrees Virgo in Western Astrology, subtracting the Ayanamsa gives 14 – 24 = –10 degrees Virgo in the Sidereal system. Since this falls before the beginning of Virgo, the Sun effectively moves backward into Leo and occupies 20 degrees Leo (–10 + 30 = 20).` } },
      { type: "paragraph", text: { en: `By contrast, if the Sun is at 28 degrees Virgo in the Tropical Zodiac, subtracting the Ayanamsa results in 4 degrees Virgo in the Sidereal Zodiac. In this case, the Sun has shifted backward but remains within the same sign.`, ja: `By contrast, if the Sun is at 28 degrees Virgo in the Tropical Zodiac, subtracting the Ayanamsa results in 4 degrees Virgo in the Sidereal Zodiac. In this case, the Sun has shifted backward but remains within the same sign.` } },
    ],
  }
];
